/*
 * camera=9: Android's fresh front-camera open replayed in its own order and timing (front_replay[]), after the sensor's
 * power-up and the D-PHYs' isolation bypass; the PDMA's queue at our IOVA, Android's buffer IOVAs mapped onto ours (as
 * camera_pdma). Then 300 polls of the front end's status (Android's interrupt acknowledgements mirrored) and the frame.
 */
static void
front_replay_capture(void)
{
	const struct sensor *c = &sensors[1];
	vm_offset_t fe = cam_io(ISPFE_FE_PHYS, 0x100000), csis = cam_io(ISPFE_CSIS_PHYS, 0xd0000);
	vm_offset_t sysreg = cam_io(ISPFE_SYSREG_PHYS, 0x1000), pmu = cam_io(0x15462000ULL, 0x2000), frame = 0, side = 0;
	uint32_t rp_mux, rp_div;
	unsigned prog = 0;
	unsigned kick = 0;
	unsigned aeloop = 1, ae_target = 44, ae_frames = 36, polls = 400;
	uint32_t ae_e = 6304u * 16 * 64;        /* (lines x gain x 64: Android's opening values, what the replay programs) */
	unsigned one_frame = 1;         /* camera_one=0: keep streaming for the 400 polls */
	uint64_t frame_pa, side_pa;
	unsigned on = 0, changed = 0, ends = 0, starts = 0;
	uint32_t last424 = 0;

	if (!(rd(pmu + 0x484) & 1u)) {
		printf("akita camera: replay: pd-ispfe is off\n");
		return;
	}
	{
		unsigned low = 0;

		PE_parse_boot_argn("camera_lowpa", &low, sizeof(low));
		cam_low = low;
	}
	if (cam_low) {          /* (the buffers below 4 GB, as camera=7's camera_lowpa) */
		frame = cam_lowmap(0x1000000);
		side = cam_lowmap(0x800000);
		pdma_mem = cam_lowmap(0x200000);
		pdma_scratch = cam_lowmap(0x400000);
		printf("akita camera: replay: the front end's buffers below 4 GB from %#llx\n", cam_low);
	} else
	if (kmem_alloc_contig(kernel_map, &frame, FRONT_BUF_MB << 20, 0xfffff, 0, 0, KMA_KOBJECT | KMA_DATA, VM_KERN_MEMORY_IOKIT) != KERN_SUCCESS ||
	    kmem_alloc_contig(kernel_map, &side, FRONT_SIDE, 0xfffff, 0, 0, KMA_KOBJECT | KMA_DATA, VM_KERN_MEMORY_IOKIT) != KERN_SUCCESS ||
	    (!pdma_mem && kmem_alloc_contig(kernel_map, &pdma_mem, 0x100000, 0xfffff, 0, 0, KMA_KOBJECT | KMA_DATA, VM_KERN_MEMORY_IOKIT) != KERN_SUCCESS) ||
	    (!pdma_scratch && kmem_alloc_contig(kernel_map, &pdma_scratch, 0x400000, 0xfffff, 0, 0, KMA_KOBJECT | KMA_DATA, VM_KERN_MEMORY_IOKIT) != KERN_SUCCESS)) {
		printf("akita camera: replay: no memory\n");
		return;
	}
	frame_pa = cam_low ? cam_low + 0x1000000 : kvtophys(frame);
	side_pa = cam_low ? cam_low + 0x800000 : kvtophys(side);
	pdma_mem_pa = cam_low ? cam_low + 0x200000 : kvtophys(pdma_mem);
	pdma_scratch_pa = cam_low ? cam_low + 0x400000 : kvtophys(pdma_scratch);
	cam_fill(frame, 0xa5a5a5a5, FRONT_BUF);
	cam_flush(frame, FRONT_BUF);
	{
		volatile uint32_t *q = (volatile uint32_t *)pdma_mem;

		cam_fill(pdma_mem, 0, 0x100000);
		cam_fill(pdma_scratch, 0, 0x400000);
		for (unsigned e = 0; e < 256; e++) {
			q[e * 4] = 0xc003;
			q[e * 4 + 1] = PDMA_IOVA + 0x1000;
			q[e * 4 + 2] = 0;
			q[e * 4 + 3] = sizeof(front_pdma_list);
		}
		cam_copy(pdma_mem + 0x1000, front_pdma_list, sizeof(front_pdma_list));
			pdma_patch_tables();
		cam_flush(pdma_mem, 0x100000);
		cam_flush(pdma_scratch, 0x400000);
	}
	/* the front end's clock as Android runs it while a camera streams (CMU_TOP mux 4 = PLL_SHARED1_D4, div 1), as camera=7
	 * sets it: on the boot's mux 1 div 5 a frame stopped after its first fifth (11-18, run-commit3) */
	rp_mux = rd(cmu_top + CMU_TOP_ISPFE_MUX);
	rp_div = rd(cmu_top + CMU_TOP_ISPFE_DIV);
	wr(cmu_top + CMU_TOP_ISPFE_DIV, (rp_div & ~0x1fu) | 1u);
	for (int i = 0; i < 1000 && (rd(cmu_top + CMU_TOP_ISPFE_DIV) & (1u << 16)); i++) {
		delay(1);
	}
	wr(cmu_top + CMU_TOP_ISPFE_MUX, (rp_mux & ~7u) | 4u);
	for (int i = 0; i < 1000 && (rd(cmu_top + CMU_TOP_ISPFE_MUX) & (1u << 16)); i++) {
		delay(1);
	}
	printf("akita camera: replay: ISPFE_NOC clock: mux %#x div %#x (was %#x %#x)\n", rd(cmu_top + CMU_TOP_ISPFE_MUX),
	    rd(cmu_top + CMU_TOP_ISPFE_DIV), rp_mux, rp_div);
	if (!ispfe_mmu(true, frame_pa, FRONT_BUF_MB, side_pa)) {
		return;
	}
	mmu_map_android(frame_pa, FRONT_BUF_MB, side_pa);
	for (unsigned i = 0; i < 3; i++) {
		static const uint64_t s2mpu_pa[3] = { 0x1c140000ULL, 0x1c180000ULL, 0x1c1c0000ULL };
		vm_offset_t s2 = cam_io(s2mpu_pa[i], 0x3000);

		wr(s2 + 0x54, 0xff);
		wr(s2 + 0x1000, 1);
	}
	/* the sensor powered (not configured: the replay does it) */
	if (!i2c_bus_up(c->bus)) {
		return;
	}
	for (on = 0; on < 4 && c->ldo[on] != 0; on++) {
		if (!slg_ldo_on(c->ldo[on], c->mv[on])) {
			goto down;
		}
	}
	delay(1000);
	pin_out(c->reset_bank, c->reset_pin, true);
	mclk(c->clk, c->clk_bank, c->clk_pin, true);
	delay(10000);
	cam_smc(SMC_PRIV_REG, PMU_CSI_PHY_ISO, PRIV_REG_WRITE, rd(pmu + 0x1ebc) | 1u);
	wr(sysreg + 0x104, 0x3ffffff);
	for (unsigned i = 0; i < sizeof(front_replay) / sizeof(front_replay[0]); i++) {
		const struct replay_ev *e = &front_replay[i];

		if (e->delay_us) {
			delay(e->delay_us);
		}
		if (e->kind == 1) {
			uint8_t v = (uint8_t)e->val;

			i2c_write16(c->bus, 0x1a, (uint16_t)e->addr, &v, 1);
			continue;
		}
		{
			uint32_t pa = e->addr, val = e->val;
			vm_offset_t va;

			if (pa == 0x1c390004) {
				val = PDMA_IOVA;        /* (the queue: ours) */
			}
			/* Android runs the start (0x2008c W1C, 0x20424 <- 8, ..., 0x200a0 <- 1) in an INTERRUPT handler: block 0
			 * raises status bit 3 first and the handler acknowledges it. What ours holds at those points; before the
			 * acknowledge, up to 500 ms waited for bit 3 */
			if (pa == 0x1c320430 || pa == 0x1c32008c || pa == 0x1c3200a0) {
				if (pa == 0x1c32008c) {
					int w = 0;

					while (!(rd(fe + 0x20424) & 8u) && w < 500) {
						delay(1000);
						w++;
					}
					printf("akita camera: replay: before the acknowledge: bit 3 %s after %d ms\n",
					    (rd(fe + 0x20424) & 8u) ? "SET" : "never set", w);
				}
				printf("akita camera: replay: before %#x <- %#x: 2008c %#x 20420 %#x 20424 %#x 20428 %#x 2042c %#x 20430 %#x 20438 %#x 2043c %#x\n",
				    pa, val, rd(fe + 0x2008c), rd(fe + 0x20420), rd(fe + 0x20424), rd(fe + 0x20428), rd(fe + 0x2042c),
				    rd(fe + 0x20430), rd(fe + 0x20438), rd(fe + 0x2043c));
			}
			if (pa >= ISPFE_FE_PHYS && pa < ISPFE_FE_PHYS + 0x100000) {
				va = fe + (pa - ISPFE_FE_PHYS);
			} else if (pa >= ISPFE_CSIS_PHYS && pa < ISPFE_CSIS_PHYS + 0xd0000) {
				va = csis + (pa - ISPFE_CSIS_PHYS);
			} else if (pa >= ISPFE_SYSREG_PHYS && pa < ISPFE_SYSREG_PHYS + 0x1000) {
				va = sysreg + (pa - ISPFE_SYSREG_PHYS);
			} else {
				continue;
			}
			wr(va, val);
		}
	}
	printf("akita camera: replay: Android's %u events done (pdma rptr %#x)\n", (unsigned)(sizeof(front_replay) / sizeof(front_replay[0])),
	    rd(fe + 0x90014));
	PE_parse_boot_argn("camera_one", &one_frame, sizeof(one_frame));
	PE_parse_boot_argn("camera_kick", &kick, sizeof(kick));
	PE_parse_boot_argn("camera_aeloop", &aeloop, sizeof(aeloop));
	PE_parse_boot_argn("camera_aetarget", &ae_target, sizeof(ae_target));
	if (aeloop && kick && !one_frame) {
		polls = 1800;           /* (~2 s: the loop settles in a dozen frames; the last frame is the one saved) */
	}
	for (unsigned it = 0; it < polls; it++) {
		uint32_t v424 = rd(fe + 0x20424), v438 = rd(fe + 0x20438), v4ac = rd(fe + 0x204ac);

		if (v424 && v424 != last424 && (starts + ends) < 12) {
			printf("akita camera: replay: %3u: 2008c %#x 20424 %#x 20438 %#x 204ac %#x 20420 %#x 2049c %#x pdma %#x/%#x 37300 %#x\n",
			    it, rd(fe + 0x2008c), v424, v438, v4ac, rd(fe + 0x20420), rd(fe + 0x2049c), rd(fe + 0x90010), rd(fe + 0x90014),
			    rd(fe + 0x37300));
		}
		if (v424) {
			if (v424 & 1u) {
				starts++;
				/* (camera_kick=1: the PDMA's next entry queued at each frame start as Android's handler does. From a
				 * poll loop it lands up to a millisecond late and the list -- with its commit -- then runs INSIDE the
				 * frame: block 0 flagged error bit 3 ~7 ms in and zero-filled the rest, 11-18 run-prog1) */
				if (kick) {
					wr(fe + 0x90010, (rd(fe + 0x90010) + 0x10) & 0xff0u);
				}
			}
			if (v424 & 0x1au) {
				ends++;
				wr(fe + 0x500e8, 3);
				wr(fe + 0x37300, 4);
				/* auto-exposure (camera_aeloop=0: off): every third finished frame measured (a change takes two frames
				 * to show), the exposure scaled towards a green mean of AE_TARGET above black -- less when more than 3 %
				 * is clipped and the mean is not far below it */
				if (aeloop && (ends % 3) == 0 && ends < ae_frames) {
					uint32_t m16, cl, want = ae_target * 16, ne;

					front_measure(frame, &m16, &cl);
					if (cl > 30 && m16 > want * 3 / 4) {
						want = m16 * 3 / 4;
					}
					if (m16 < 8) {
						m16 = 8;
					}
					ne = (uint32_t)(((uint64_t)ae_e * want) / m16);
					if (ne > ae_e * 4) {
						ne = ae_e * 4;
					}
					if (ne < ae_e / 4) {
						ne = ae_e / 4;
					}
					if (ne > 6304u * 16 * 64) {
						ne = 6304u * 16 * 64;
					}
					printf("akita camera: ae: frame %u: green mean %u.%u above black, %u.%u %% clipped; exposure x%u.%02u\n", ends,
					    m16 / 16, (m16 % 16) * 10 / 16, cl / 10, cl % 10, ne / (ae_e ? ae_e : 1),
					    (uint32_t)(((uint64_t)ne * 100 / (ae_e ? ae_e : 1)) % 100));
					if (ne > ae_e + ae_e / 12 || ne < ae_e - ae_e / 12) {
						ae_e = ne;
						front_set_exposure(c->bus, ae_e);
					}
				}
			}
			wr(fe + 0x2008c, 1);
			wr(fe + 0x20404, 0);
			wr(fe + 0x20424, v424);
			wr(fe + 0x20438, v438);
			wr(fe + 0x2044c, 0);
			wr(fe + 0x20110, 0);
		}
		/* through the first frame: block 0's progress counters (+0xbc/+0xc0 move with the lines on Android), its error words,
		 * the link's interrupt/error sources (CSIS_INT_SRC0/1, ERR_LOST_FS/FE, ERR_VRESOL/HRESOL: is-hw-csi-v5 names) */
		if (starts >= 1 && prog < 40 && (it % 6) == 0) {
			prog++;
			printf("akita camera: replay: prog %3u: 204a0 %#x 204bc %#x 204c0 %#x 204c4 %#x 20420 %#x 20438 %#x 204ac %#x 37300 %#x 20708 %#x"
			    " | link src0 %#x src1 %#x lostfs %#x lostfe %#x vres %#x hres %#x fs %#x fe %#x | ch0 +b0 %#x +b4 %#x\n", it,
			    rd(fe + 0x204a0), rd(fe + 0x204bc), rd(fe + 0x204c0), rd(fe + 0x204c4), rd(fe + 0x20420), rd(fe + 0x20438),
			    rd(fe + 0x204ac), rd(fe + 0x37300), rd(fe + 0x20708), rd(csis + 0x60014), rd(csis + 0x6001c), rd(csis + 0x60614),
			    rd(csis + 0x6061c), rd(csis + 0x60624), rd(csis + 0x6062c), rd(csis + 0x60024), rd(csis + 0x6002c),
			    rd(fe + 0x205b0), rd(fe + 0x205b4));
		}
		if ((v424 & 0x1au) == 0x1au && one_frame) {
			wr(fe + 0x20540, 0);    /* (the first complete frame kept: channel 0 off before a later frame can touch it) */
			printf("akita camera: replay: first frame end at %u, channel 0 stopped\n", it);
			break;
		}
		last424 = v424;
		delay(1000);
	}
	{
		uint8_t zero = 0;

		i2c_write16(c->bus, 0x1a, 0x0100, &zero, 1);
	}
	delay(50000);
	cam_flush(frame, FRONT_BUF);
	for (unsigned i = 0; i < FRONT_BUF; i++) {
		changed += ((volatile uint8_t *)frame)[i] != 0xa5;
	}
	printf("akita camera: replay: %u frame starts, %u frame ends, %u bytes of the frame written\n", starts, ends, changed);
	{
		unsigned last = 0, firstgap = 0;

		for (unsigned i = FRONT_BUF; i > 0; i -= 4) {
			if (*(const volatile uint32_t *)(frame + i - 4) != 0xa5a5a5a5u) {
				last = i;
				break;
			}
		}
		for (unsigned i = 0; i < FRONT_BUF; i += 4) {
			if (*(const volatile uint32_t *)(frame + i) == 0xa5a5a5a5u) {
				firstgap = i;
				break;
			}
		}
		printf("akita camera: replay: the frame's first untouched word at %#x (line %u), last written byte before %#x\n",
		    firstgap, firstgap / FRONT_STRIDE, last);
	}
	for (unsigned m = 0; m < 3; m++) {
		static const uint64_t mmus[3] = { 0x1c110000ULL, 0x1c150000ULL, 0x1c190000ULL };
		vm_offset_t r = cam_io(mmus[m], 0x10000);

		printf("akita camera: replay: SysMMU %#llx: CTRL_VM %#x FAULT STATUS %#x VA %#x INFO %#x %#x %#x\n", mmus[m], rd(r + 0x8000),
		    rd(r + 0x8060), rd(r + 0x8070), rd(r + 0x8074), rd(r + 0x8078), rd(r + 0x807c));
	}
	if (changed) {
		frame_thumb(frame, FRONT_STRIDE, FRONT_HEIGHT, 4208);
		frame_save(frame, (size_t)FRONT_STRIDE * FRONT_HEIGHT, "/private/var/mobile/Media/hakios-klog/front.raw");
	}
	for (unsigned row = 0; row < FRONT_HEIGHT && changed; row += 1024) {
		const uint8_t *b = (const uint8_t *)frame + row * FRONT_STRIDE + 2000;

		printf("akita camera: replay: row %u: %02x %02x %02x %02x %02x %02x %02x %02x\n", row, b[0], b[1], b[2], b[3], b[4], b[5],
		    b[6], b[7]);
	}
	wr(fe + 0x90000, 0);
	ispfe_mmu(false, 0, 0, 0);
	wr(sysreg + 0x500, rd(sysreg + 0x500) & ~FRONT_DPHY_RESET_BITS);
	wr(cmu_top + CMU_TOP_ISPFE_MUX, (rd(cmu_top + CMU_TOP_ISPFE_MUX) & ~7u) | (rp_mux & 7u));
	delay(100);
	wr(cmu_top + CMU_TOP_ISPFE_DIV, (rd(cmu_top + CMU_TOP_ISPFE_DIV) & ~0x1fu) | (rp_div & 0x1fu));
	cam_smc(SMC_PRIV_REG, PMU_CSI_PHY_ISO, PRIV_REG_WRITE, rd(pmu + 0x1ebc) & ~1u);
down:
	mclk(c->clk, c->clk_bank, c->clk_pin, false);
	pin_out(c->reset_bank, c->reset_pin, false);
	while (on-- > 0) {
		slg_ldo_off(c->ldo[on]);
	}
	printf("akita camera: replay: front camera powered down\n");
}

/*
 * camera=10: the PDMA alone, as a probe of the front end's bus path: a list of one write (fe +0x20554 <- 0x1234 + try)
 * queued 5 times through the SysMMUs (IOVA PDMA_IOVA, 1 MiB section onto our buffer) and 5 times with them off (physical
 * addresses); each try says whether the queue was read (read pointer) and the list executed (the register).
 */
static void
pdma_probe(void)
{
	vm_offset_t fe = cam_io(ISPFE_FE_PHYS, 0x100000), pmu = cam_io(0x15462000ULL, 0x2000), mem = 0, lowtab = 0;
	uint64_t mem_pa = 0, lowtab_pa = 0;

	if (!(rd(pmu + 0x484) & 1u)) {
		printf("akita camera: pdma probe: pd-ispfe is off\n");
		return;
	}
	{
		unsigned low = 0;       /* camera_lowpa=ADDR: the queue/list (mem) and the SysMMU table at a physical address below
		                         * 4 GB (outside XNU; mapped uncached): mem at ADDR, the table at ADDR + 0x100000 */

		PE_parse_boot_argn("camera_lowpa", &low, sizeof(low));
		if (low) {
			mem = ml_io_map(low, 0x100000);
			mem_pa = low;
			lowtab_pa = (uint64_t)low + 0x100000;
			lowtab = ml_io_map(lowtab_pa, 0x40000);
			printf("akita camera: pdma probe: buffers below 4 GB: mem %#llx, table %#llx\n", mem_pa, lowtab_pa);
		}
	}
	if (!mem) {
		if (kmem_alloc_contig(kernel_map, &mem, 0x100000, 0xfffff, 0, 0, KMA_KOBJECT | KMA_DATA, VM_KERN_MEMORY_IOKIT) != KERN_SUCCESS) {
			return;
		}
		mem_pa = kvtophys(mem);
	}
	if (!mmu_flpt && kmem_alloc_contig(kernel_map, &mmu_flpt, 0x40000, 0x3ffff, 0, 0, KMA_KOBJECT | KMA_DATA, VM_KERN_MEMORY_IOKIT) != KERN_SUCCESS) {
		return;
	}
	if (!mmu_flpt_pa) {
		mmu_flpt_pa = kvtophys(mmu_flpt);
	}
	{
		unsigned s2off = 1;

		PE_parse_boot_argn("camera_s2off", &s2off, sizeof(s2off));
		for (unsigned i = 0; s2off && i < 3; i++) {
			static const uint64_t s2mpu_pa[3] = { 0x1c140000ULL, 0x1c180000ULL, 0x1c1c0000ULL };
			vm_offset_t s2 = cam_io(s2mpu_pa[i], 0x3000);

			wr(s2 + 0x54, 0xff);
			wr(s2 + 0x1000, 1);
		}
	}
	for (unsigned mode = 0; mode < 2; mode++) {
		if (mode == 0) {        /* through the SysMMUs: our table, PDMA_IOVA's section onto mem */
			ispfe_mmu(true, mem_pa, 1, mem_pa);
			((uint32_t *)mmu_flpt)[PDMA_IOVA >> 20] = (uint32_t)(mem_pa >> 4) | 2u;
			cam_flush(mmu_flpt, 0x40000);
			if (lowtab) {   /* the table below 4 GB instead: a copy, and the SysMMUs pointed at it */
				for (unsigned k = 0; k < 0x10000; k++) {
					*(volatile uint32_t *)(lowtab + k * 4) = ((uint32_t *)mmu_flpt)[k];
				}
				__asm__ volatile ("dsb sy" ::: "memory");
			}
			for (unsigned m = 0; m < 3; m++) {
				static const uint64_t mmus[3] = { 0x1c110000ULL, 0x1c150000ULL, 0x1c190000ULL };
				vm_offset_t r = cam_io(mmus[m], 0x10000);

				if (lowtab) {
					wr(r + 0x8404, (uint32_t)(lowtab_pa >> 12));
				}
				wr(r + 0x8010, 1);
			}
		} else {
			ispfe_mmu(false, 0, 0, 0);
		}
		/* the queue entry's first word per try (Android's is 0xc003: which bits make the list wait for an event?) */
		static const uint32_t pd_flags[5] = { 0xc003, 0x0003, 0x4003, 0x8003, 0x0000 };

		for (unsigned t = 0; t < 5; t++) {
			uint32_t *q = (uint32_t *)mem, *l = (uint32_t *)(mem + 0x1000);
			uint64_t qa = mode ? mem_pa : PDMA_IOVA, la = qa + 0x1000;
			uint32_t want = 0x1234 + t + mode * 16, r14 = 0, reg = 0;

			for (unsigned k = 0; k < 0x800; k++) {
				((volatile uint32_t *)mem)[k] = 0;
			}
			((volatile uint32_t *)l)[0] = 0x0000400b; ((volatile uint32_t *)l)[1] = 0; ((volatile uint32_t *)l)[2] = 0x00018002;
			((volatile uint32_t *)l)[3] = 0x20554; ((volatile uint32_t *)l)[4] = want;
			((volatile uint32_t *)q)[0] = pd_flags[t]; ((volatile uint32_t *)q)[1] = (uint32_t)la;
			((volatile uint32_t *)q)[2] = (uint32_t)(la >> 32); ((volatile uint32_t *)q)[3] = 20;
			if (!lowtab) {
				flush_dcache(mem, 0x2000, FALSE);
			}
			__asm__ volatile ("dsb sy" ::: "memory");
			wr(fe + 0x20554, 0);
			wr(fe + 0x90000, 0);
			wr(fe + 0x9002c, 1);
			wr(fe + 0x90040, 0x1f);
			wr(fe + 0x90004, (uint32_t)qa);
			wr(fe + 0x90008, (uint32_t)(qa >> 32));
			wr(fe + 0x9000c, 0x3e8);
			wr(fe + 0x90010, 0);
			wr(fe + 0x90000, 1);
			wr(fe + 0x90028, 1);
			wr(fe + 0x90010, 0x10);
			for (int i = 0; i < 100; i++) {
				delay(100);
				r14 = rd(fe + 0x90014);
				reg = rd(fe + 0x20554);
				if (reg == want) {
					break;
				}
			}
			printf("akita camera: pdma probe: %s try %u (flags %#x): rptr %#x, fe+0x20554 %#x (%s) [pdma +00 %#x +18 %#x +1c %#x +24 %#x +28 %#x +30 %#x +38 %#x]\n",
			    mode ? "physical" : "IOVA", t, pd_flags[t], r14, reg, reg == want ? "list RAN" : "not run", rd(fe + 0x90000), rd(fe + 0x90018),
			    rd(fe + 0x9001c), rd(fe + 0x90024), rd(fe + 0x90028), rd(fe + 0x90030), rd(fe + 0x90038));
		}
		for (unsigned i = 0; i < 3; i++) {
			static const uint64_t s2mpu_pa[3] = { 0x1c140000ULL, 0x1c180000ULL, 0x1c1c0000ULL };
			static const uint64_t mmus[3] = { 0x1c110000ULL, 0x1c150000ULL, 0x1c190000ULL };
			vm_offset_t s2 = cam_io(s2mpu_pa[i], 0x3000), r = cam_io(mmus[i], 0x10000);

			printf("akita camera: pdma probe: after %s: S2MPU %#llx FAULT %#x (vid0 %#x %#x %#x); SysMMU %#llx CTRL_VM %#x FAULT %#x VA %#x INFO %#x %#x %#x\n",
			    mode ? "physical" : "IOVA", s2mpu_pa[i], rd(s2 + 0x2000), rd(s2 + 0x2004), rd(s2 + 0x2008), rd(s2 + 0x2010), mmus[i],
			    rd(r + 0x8000), rd(r + 0x8060), rd(r + 0x8070), rd(r + 0x8074), rd(r + 0x8078), rd(r + 0x807c));
		}
	}
	wr(fe + 0x90000, 0);
}

struct pdma_tab { uint16_t word; uint32_t dest, off, len; };

